div_projekt_acker_ok(p) if {
	p.land_use == "arable"
	p.mfa.nutzungsart == "Grünbrache"
	"DIV" in p.mfa.codes
	"EBW" in p.mfa.codes
}

div_projekt_acker_ok(p) if {
