acker_div_codierung_ok(nutzung, code, _) if {
	code == "DIV"
	nutzung in {"Grünbrache", "Sonstiges Feldfutter"}
}

acker_div_codierung_ok(nutzung, code, jahr) if {
	jahr >= 2025
	code == "DIV"
	nutzung == "Ackerweide"
}

acker_div_codierung_ok(nutzung, code, _) if {
	code == "DIVRS"
	nutzung == "Sonstiges Feldfutter"
}

acker_div_codierung_ok(nutzung, code, jahr) if {
