	e.starkwuechsig
	e.grosskronig
	e.stamm in {"Hochstamm", "Halbstamm"}
	e.baumuebergreifendes_stuetzgeruest == false
	wildform_ok(e)
}

wildform_ok(e) if e.wildform == false
wildform_ok(e) if e.obstart in {"Apfel", "Birne", "Kirsche"}

hecke_anlage_ok(h, jahr) if {
