	tag(h.anlagedatum) <= stichtag(jahr, "05-15")
	h.eigener_acker_angrenzend
	h.laengsseite_wald_lse == false
	h.landeskonzept
	h.gis_bestaetigt
	h.ueberwiegend_strauch_obst
	h.breite_m >= 5
	h.breite_m <= 20
	h.kraut_prozent >= 20
}

fallen_anlagetermin_ok(f) if {
